from pathlib import Path
p=Path('worker.js'); s=p.read_text()
assert "const VERSION = 'RADAR v0.4.7.51 Cloud';" in s
start=s.index('async function artistRadarScan(input,env)')
end=s.index('\nfunction trackRadarAlgorithmic(name)',start)
new_backend=r'''function artistRadarNameMatch(a,b){const x=normalize(a).replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim(),y=normalize(b).replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim();if(!x||!y)return false;if(x===y||x.includes(y)||y.includes(x))return true;const xs=x.split(' ').filter(w=>w.length>2),ys=new Set(y.split(' ').filter(w=>w.length>2));const hit=xs.filter(w=>ys.has(w)).length;return hit>=Math.max(2,Math.ceil(xs.length*.6))}
async function artistRadarVerifyCandidate(x,cat,env){const tracks=[...x.tracks].slice(0,2),domains=new Set(),evidence=[],exactSpotify=new Set();for(const track of tracks){const q='"'+track+'" "'+cat.artist+'" "'+String(x.name||'').replace(/"/g,'')+'"';const b=await smartSearch(q,env,10);for(const r of b.results||[]){const blob=String((r.title||'')+' '+(r.description||'')+' '+(r.url||'')),text=normalize(blob);if(!text.includes(normalize(track))||!text.includes(normalize(cat.artist)))continue;const host=(()=>{try{return new URL(r.url||'').hostname.replace(/^www\./,'')}catch(e){return''}})();const pu=cleanPlaylistUrl(r.url||'')||cleanPlaylistUrl(blob);const samePlaylist=(pu&&cleanPlaylistUrl(x.spotifyUrl)===pu)||artistRadarNameMatch(x.name,(r.title||'')+' '+(r.description||''));if(!samePlaylist)continue;if(host)domains.add(host);if(pu&&cleanPlaylistUrl(x.spotifyUrl)===pu)exactSpotify.add(track);if(evidence.length<4)evidence.push(blob.slice(0,260))}}const independent=[...domains].filter(Boolean),exactCount=exactSpotify.size;let verification='WEB_EVIDENCE',verificationLabel='SOLO EVIDENZA WEB',verificationScore=35;if(exactCount>=1&&independent.some(d=>d!=='open.spotify.com')){verification='CONFIRMED';verificationLabel='CONFERMATO PUBBLICAMENTE';verificationScore=90}else if(exactCount>=1||independent.length>=2){verification='PROBABLE';verificationLabel='PROBABILE';verificationScore=68}return {...x,verification,verificationLabel,verificationScore,verificationDomains:independent,verificationEvidence:evidence}}
async function artistRadarScan(input,env){const cat=await artistRadarCatalog(input?.artist,env),playlistMap=new Map(),foundTracks=new Set();const ingest=(track,batch,stage)=>{for(const r of batch.results||[]){let clean=cleanPlaylistUrl(r.url||'');if(!clean){const m=String((r.title||'')+' '+(r.description||'')).match(/https?:\/\/open\.spotify\.com\/playlist\/[A-Za-z0-9]+/i);if(m)clean=cleanPlaylistUrl(m[0])}if(!clean)continue;const blob=String((r.title||'')+' '+(r.description||'')),text=normalize(blob);if(!text.includes(normalize(track))||!text.includes(normalize(cat.artist)))continue;const id=new URL(clean).pathname.split('/').filter(Boolean)[1];if(!id)continue;foundTracks.add(normalize(track));let x=playlistMap.get(id);if(!x){x={playlistId:id,spotifyUrl:clean,name:String(r.title||'Spotify playlist').trim(),owner:'',tracks:new Set(),evidence:[],stages:new Set()};playlistMap.set(id,x)}x.tracks.add(track);x.stages.add(stage);if(x.evidence.length<3)x.evidence.push(blob.slice(0,240))}};const fastJobs=cat.tracks.map(t=>({track:t.name,p:smartSearch('\"'+t.name+'\" \"'+cat.artist+'\" Spotify playlist',env,12)}));const fast=await Promise.all(fastJobs.map(async j=>({track:j.track,batch:await j.p})));for(const j of fast)ingest(j.track,j.batch,'fast');const missing=cat.tracks.filter(t=>!foundTracks.has(normalize(t.name))).slice(0,5);if(missing.length&&playlistMap.size<8){const deepJobs=[];for(const t of missing){deepJobs.push({track:t.name,p:smartSearch('site:open.spotify.com/playlist \"'+t.name+'\" \"'+cat.artist+'\"',env,16)});deepJobs.push({track:t.name,p:smartSearch('\"'+t.name+'\" \"'+cat.artist+'\" playlist Spotify -album -track',env,16)})}const deep=await Promise.all(deepJobs.map(async j=>({track:j.track,batch:await j.p})));for(const j of deep)ingest(j.track,j.batch,'deep')}const candidates=[...playlistMap.values()].slice(0,12);const enriched=await Promise.all(candidates.map(async x=>{try{const ident=await spotifyPlaylistIdentity(x.spotifyUrl,env);if(ident){x.name=ident.name||x.name;x.owner=ident.owner||''}}catch(e){}return x}));const filtered=[];const an=normalize(cat.artist).replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim();for(const x of enriched){const pn=normalize(x.name).replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim();if(trackRadarAlgorithmic(x.name)||pn.startsWith(an+' radio'))continue;const tracks=[...x.tracks],stages=[...x.stages];filtered.push({...x,tracks,trackCount:tracks.length,stage:stages.includes('deep')?'deep':'fast'})}const verified=await Promise.all(filtered.slice(0,8).map(x=>artistRadarVerifyCandidate(x,cat,env)));verified.sort((a,b)=>b.verificationScore-a.verificationScore||b.trackCount-a.trackCount||String(a.name).localeCompare(String(b.name)));return {artist:cat.artist,tracks:cat.tracks,playlists:verified,mode:'verified',deepTracks:missing.map(x=>x.name),verificationSummary:{confirmed:verified.filter(x=>x.verification==='CONFIRMED').length,probable:verified.filter(x=>x.verification==='PROBABLE').length,web:verified.filter(x=>x.verification==='WEB_EVIDENCE').length}}}'''
s=s[:start]+new_backend+s[end:]
old_front="""async function scanArtistRadar(){const input=document.getElementById('artistRadarInput'),btn=document.getElementById('artistRadarScan'),st=document.getElementById('artistRadarStatus'),sum=document.getElementById('artistRadarSummary'),box=document.getElementById('artistRadarResults');if(!input||!btn||!st||!sum||!box)return;const artist=input.value.trim();if(!artist){st.textContent='Inserisci il nome artista o il link Spotify.';return}btn.disabled=true;st.textContent='Analizzo catalogo e placement pubblici…';sum.style.display='none';box.innerHTML='';try{const r=await fetch('/api/artist-radar',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({artist:artist})});const d=await r.json();if(!r.ok||d.error)throw new Error(d.error||'Errore Artist Radar');const tracks=Array.isArray(d.tracks)?d.tracks:[],rows=Array.isArray(d.playlists)?d.playlists:[];sum.style.display='block';sum.textContent=(d.artist||artist)+' · '+tracks.length+' tracce analizzate · '+rows.length+' playlist rilevate';st.textContent=rows.length?'Trovate '+rows.length+' playlist pubblicamente rilevabili.':'Nessuna playlist pubblicamente rilevabile.';for(const x of rows){const card=document.createElement('div');card.className='result';const h=document.createElement('h3');h.textContent=x.name||'Spotify playlist';const meta=document.createElement('div');meta.className='muted';meta.textContent=(x.owner?x.owner+' · ':'')+(x.trackCount||0)+' tracce dell’artista rilevate';const names=document.createElement('div');names.className='muted';names.style.marginTop='6px';names.textContent=(x.tracks||[]).slice(0,8).join(' · ');card.append(h,meta,names);if(x.spotifyUrl){const a=document.createElement('a');a.href=x.spotifyUrl;a.target='_blank';a.rel='noopener';a.className='btn secondary';a.style.cssText='display:inline-block;margin-top:10px;text-decoration:none';a.textContent='Apri Spotify';card.appendChild(a)}box.appendChild(card)}}catch(e){st.textContent=e.message||'Errore Artist Radar'}finally{btn.disabled=false}}"""
assert old_front in s
new_front="""async function scanArtistRadar(){const input=document.getElementById('artistRadarInput'),btn=document.getElementById('artistRadarScan'),st=document.getElementById('artistRadarStatus'),sum=document.getElementById('artistRadarSummary'),box=document.getElementById('artistRadarResults');if(!input||!btn||!st||!sum||!box)return;const artist=input.value.trim();if(!artist){st.textContent='Inserisci il nome artista o il link Spotify.';return}btn.disabled=true;st.textContent='Analizzo catalogo, placement e verifiche pubbliche…';sum.style.display='none';box.innerHTML='';try{const r=await fetch('/api/artist-radar',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({artist:artist})});const d=await r.json();if(!r.ok||d.error)throw new Error(d.error||'Errore Artist Radar');const tracks=Array.isArray(d.tracks)?d.tracks:[],rows=Array.isArray(d.playlists)?d.playlists:[],vs=d.verificationSummary||{};sum.style.display='block';sum.textContent=(d.artist||artist)+' · '+tracks.length+' tracce · '+rows.length+' playlist · '+(vs.confirmed||0)+' confermate · '+(vs.probable||0)+' probabili';st.textContent=rows.length?'Verifica completata: '+(vs.confirmed||0)+' confermate, '+(vs.probable||0)+' probabili, '+(vs.web||0)+' solo evidenza web.':'Nessuna playlist pubblicamente rilevabile.';for(const x of rows){const card=document.createElement('div');card.className='result';const h=document.createElement('h3');h.textContent=x.name||'Spotify playlist';const verify=document.createElement('div');verify.className='muted';verify.style.cssText='margin:6px 0;font-weight:900';verify.textContent=(x.verification==='CONFIRMED'?'🟢 ':x.verification==='PROBABLE'?'🟡 ':'⚪ ')+(x.verificationLabel||'SOLO EVIDENZA WEB');const meta=document.createElement('div');meta.className='muted';meta.textContent=(x.owner?x.owner+' · ':'')+(x.trackCount||0)+' tracce dell’artista rilevate';const names=document.createElement('div');names.className='muted';names.style.marginTop='6px';names.textContent=(x.tracks||[]).slice(0,8).join(' · ');card.append(h,verify,meta,names);if(x.spotifyUrl){const a=document.createElement('a');a.href=x.spotifyUrl;a.target='_blank';a.rel='noopener';a.className='btn secondary';a.style.cssText='display:inline-block;margin-top:10px;text-decoration:none';a.textContent='Apri Spotify';card.appendChild(a)}box.appendChild(card)}}catch(e){st.textContent=e.message||'Errore Artist Radar'}finally{btn.disabled=false}}"""
s=s.replace(old_front,new_front,1)
s=s.replace("const VERSION = 'RADAR v0.4.7.51 Cloud';","const VERSION = 'RADAR v0.4.7.52 Cloud';",1)
